package cn.dreamingfish.launcher.vanilla;
import java.util.*;
public record VanillaPlan(String versionId,String metadataSha1,Platform platform,Integer requiredJavaMajor,List<InstallFile> files,long totalBytes,String fabricVersion,cn.dreamingfish.launcher.loaders.LoaderIdentity component) {
 public VanillaPlan(String versionId,String metadataSha1,Platform platform,Integer requiredJavaMajor,List<InstallFile> files,long totalBytes,String fabricVersion){this(versionId,metadataSha1,platform,requiredJavaMajor,files,totalBytes,fabricVersion,null);}
 public VanillaPlan(String versionId,String metadataSha1,Platform platform,Integer requiredJavaMajor,List<InstallFile> files,long totalBytes){this(versionId,metadataSha1,platform,requiredJavaMajor,files,totalBytes,null);}
 public VanillaPlan {if(versionId==null||versionId.isBlank()||metadataSha1==null||!metadataSha1.matches("[0-9a-f]{40}")||platform==null||requiredJavaMajor!=null&&(requiredJavaMajor<1||requiredJavaMajor>100))throw new IllegalArgumentException("原版计划字段无效");files=List.copyOf(files);if(files.isEmpty()||files.size()>100000)throw new IllegalArgumentException("原版目标数量超限");SafeInstallPath.checkDistinct(files.stream().map(InstallFile::relativePath).toList());
  var unique=new HashMap<String,Long>();long sum=0;try{for(var file:files){var spec=file.download();if(spec.expectedSize()<0)throw new IllegalArgumentException("计划文件必须具有确定长度");String key=spec.digest().algorithm()+":"+spec.digest().hex();Long prior=unique.putIfAbsent(key,spec.expectedSize());if(prior!=null&&prior!=spec.expectedSize())throw new IllegalArgumentException("相同摘要的长度冲突");if(prior==null)sum=Math.addExact(sum,spec.expectedSize());}}catch(ArithmeticException error){throw new IllegalArgumentException("原版计划总量溢出");}if(sum>20L*1024*1024*1024)throw new IllegalArgumentException("原版计划超过 20 GiB");totalBytes=sum;
  if(component!=null&&(fabricVersion!=null||files.stream().noneMatch(f->f.relativePath().toString().replace('\\','/').equals(component.kind()==cn.dreamingfish.launcher.GameInstance.LoaderKind.QUILT?component.profilePath():"versions/installer.jar"))))throw new IllegalArgumentException("加载器固定计划缺少profile或安装描述");
  if(fabricVersion!=null&&(!fabricVersion.matches("[A-Za-z0-9][A-Za-z0-9_.+\\-]{0,127}")||files.stream().noneMatch(f->f.relativePath().toString().replace('\\','/').equals("versions/fabric.json"))))throw new IllegalArgumentException("Fabric固定计划缺少有效版本或元数据");
 }
}
